(() => {
  'use strict';
  const STORE='career-quest-design-v3', SESSION='career-quest-demo-session';
  let storageIssue=false;
  function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback;}catch{storageIssue=true;return fallback;}}
  let db=read(STORE,null); if(!db||db.version!==3||!Array.isArray(db.employees))db=CQSeed();
  let session=read(SESSION,{role:'employee'}), view={filter:'Все',query:'',format:'Все форматы',skill:'Все навыки',tab:'all'}, chat=[];
  const app=document.getElementById('app'), dialog=document.getElementById('dialog');
  let lastFocus=null, toastTimer, activeRoute='', menuOpen=false;
  const roleNames={employee:'Сотрудник',manager:'Руководитель',hr:'HR-партнёр',admin:'Администратор'};
  const starts={employee:'/app/home',manager:'/manager/team',hr:'/hr/overview',admin:'/admin/overview'};
  const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',route:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="M6 7v7a4 4 0 0 0 4 4h6M10 5h7a3 3 0 0 1 0 6h-5"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M8 15h2m4 0h2M8 18h2"/>',sparkles:'<path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4zM20 2v4m-2-2h4"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1v15"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',users:'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M22 21v-2a4 4 0 0 0-3-3.87"/><circle cx="9" cy="7" r="4"/><path d="M16 3a4 4 0 0 1 0 8"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a6 6 0 0 1 6-6h4a6 6 0 0 1 6 6v2"/>',settings:'<path d="M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1m0-12.8-2.1 2.1m-8.6 8.6-2.1 2.1"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 8.5a2.5 2.5 0 1 1 4 2c-1 .5-1.5 1-1.5 2.5M12 17h.01"/>',logout:'<path d="M9 3H4v18h5M9 12h12m-4-4 4 4-4 4"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M3 16v5h18v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M3 16v5h18v-5"/>',plus:'<path d="M12 5v14M5 12h14"/>',chart:'<path d="M4 3v17h17M8 15v-4m5 4V6m5 9V9"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9S4 17 4 12V6zM8 12l3 3 5-6"/>',layers:'<path d="m12 3 10 6-10 6L2 9zM2 14l10 6 10-6"/>',code:'<path d="m8 7-5 5 5 5m8-10 5 5-5 5m-5-12-2 14"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0z"/><circle cx="12" cy="10" r="2.5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m3 5 9 7 9-7"/>',send:'<path d="m22 2-7 20-4-9-9-4zM22 2 11 13"/>',edit:'<path d="m15 4 5 5M3 21l5-1L21 7a2 2 0 0 0-5-5L3 15z"/>',file:'<path d="M14 2H5v20h14V7zM14 2v5h5M8 12h8M8 16h6"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H3v18h18v-7"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M5 7a8 8 0 0 1 13-2l2 3M4 16l2 3a8 8 0 0 0 13-2"/>'};
  function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.layers}</svg>`;}
  function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
  const person=()=>db.employees.find(e=>e.id===db.profile)||db.employees[0];
  const initials=name=>String(name).split(/\s+/).filter(Boolean).slice(0,2).map(n=>n[0]).join('');
  const activity=id=>db.activities.find(a=>a.id===id);
  const myEnrollments=(id=person().id)=>db.enrollments.filter(e=>e.employeeId===id);
  const visibleNotifications=()=>db.notifications.filter(n=>(n.role||'employee')===session?.role&&(session?.role!=='employee'||n.employeeId===person().id));
  function calculateReadiness(p){if(!p.skills.length)return 0;const weights=p.skills.map((_,i)=>[.5,.3,.2][i]??.2),sum=weights.reduce((a,b)=>a+b,0);return Math.round(p.skills.reduce((total,s,i)=>total+Math.min(1,s.level/Math.max(1,s.target))*weights[i],0)/sum*100);}
  function promoteWaitlist(id){const a=activity(id);if(!a||a.status!=='published'||new Date(a.date)<=new Date())return;const waiting=db.enrollments.filter(e=>e.activityId===id&&e.status==='waitlisted').sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt));for(const e of waiting){if(places(a)<=0)break;e.status='enrolled';notify('Место на активности подтверждено',a.title,'/app/enrollments/'+e.id,e.employeeId);audit('Подтверждение места из листа ожидания',a.title);}}
  const eligible=(a,p=person())=>!a.roles.length||a.roles.includes(p.role);
  const catalog=()=>db.activities.filter(a=>a.status==='published'&&eligible(a));
  function recommended(p=person()){return db.activities.find(a=>a.id===p.recommended&&a.status==='published')||db.activities.find(a=>a.status==='published'&&eligible(a,p));}
  function save(){try{localStorage.setItem(STORE,JSON.stringify(db));localStorage.setItem(SESSION,JSON.stringify(session));return true;}catch{storageIssue=true;toast('Не удалось сохранить на устройстве. Изменения доступны до закрытия страницы.');return false;}}
  function audit(action,object){db.audit.unshift({id:crypto.randomUUID(),date:new Date().toISOString(),actor:roleNames[session?.role]||'Гость',action,object});}
  function notify(title,text,route,employeeId=person().id){db.notifications.unshift({id:crypto.randomUUID(),title,text,route,employeeId,read:false,date:new Date().toISOString()});}
  function date(value,short=false){return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:short?'short':'long',timeZone:db.preferences.timezone}).format(new Date(value));}
  function time(value){return new Intl.DateTimeFormat('ru-RU',{hour:'2-digit',minute:'2-digit',timeZone:db.preferences.timezone}).format(new Date(value));}
  function dateTile(value){const d=new Date(value);return `<div class="date-tile"><strong>${new Intl.DateTimeFormat('ru',{day:'numeric',timeZone:db.preferences.timezone}).format(d)}</strong><span>${new Intl.DateTimeFormat('ru',{month:'short',timeZone:db.preferences.timezone}).format(d).replace('.','')}</span></div>`;}
  function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
  const btn=(label,action,style='',ico='',extra='')=>`<button type="button" class="button ${style}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
  const link=(label,path,style='',ico='')=>`<a class="button ${style}" href="#${path}">${ico?icon(ico):''}${label}</a>`;
  const textLink=(label,path)=>`<a class="text-link" href="#${path}">${label}${icon('arrow')}</a>`;
  const tag=(text,color='',ico='')=>`<span class="tag ${color}">${ico?icon(ico):''}${esc(text)}</span>`;
  const banner=(text,type='')=>`<div class="info-banner ${type}">${icon(type==='success'?'check':'info')}<p>${text}</p></div>`;
  const statusNames={enrolled:'Вы записаны',waitlisted:'Лист ожидания',submitted:'На проверке',revision:'Нужны изменения',verified:'Подтверждено',cancelled:'Отменено',published:'Опубликовано',draft:'Черновик',archived:'В архиве'};
  const statusColor={enrolled:'blue',waitlisted:'orange',submitted:'violet',revision:'orange',verified:'green',cancelled:'',published:'green',draft:'orange',archived:''};
  const status=s=>tag(statusNames[s]||s,statusColor[s],s==='verified'?'check':'');
  function empty(title,text,action='',ico='grid',compact=false){return `<div class="empty ${compact?'compact':''}"><div class="tile-icon">${icon(ico)}</div><h2>${title}</h2><p>${text}</p>${action}</div>`;}
  function heading(title,subtitle='',actions='',eyebrow=''){return `<header class="page-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1 tabindex="-1">${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${actions?`<div class="page-tools">${actions}</div>`:''}</header>`;}
  function stat(value,label,ico,color=''){return `<div class="card stat"><div class="stat-icon ${color}">${icon(ico)}</div><div><strong>${value}</strong><p>${label}</p></div></div>`;}
  function go(path){if(location.hash==='#'+path)render();else location.hash=path;}
  const navigation={employee:[['home','Мой план','/app/home'],['route','Карта навыков','/app/development-plan'],['grid','Каталог активностей','/app/catalog'],['calendar','Мои активности','/app/enrollments'],['sparkles','AI-навигатор','/app/navigator']],manager:[['users','Моя команда','/manager/team'],['check','Проверка результатов','/manager/reviews']],hr:[['chart','Обзор программы','/hr/overview'],['grid','Активности','/hr/activities'],['users','Сотрудники','/hr/people'],['layers','Аналитика навыков','/hr/analytics']],admin:[['grid','Обзор системы','/admin/overview'],['users','Пользователи и роли','/admin/users'],['layers','Справочник навыков','/admin/skills'],['target','Матрицы ролей','/admin/role-matrices'],['code','Интеграции','/admin/integrations'],['file','Журнал действий','/admin/audit-log']]};
  function titleFor(path){return [...Object.values(navigation).flat(),['','Уведомления','/app/notifications'],['','Профиль','/app/profile'],['','Настройки','/app/settings'],['','Помощь','/help']].filter(x=>path.startsWith(x[2])).sort((a,b)=>b[2].length-a[2].length)[0]?.[1]||'Career Quest';}
  function shell(content,path){const role=session?.role||'employee',p=person(),nav=navigation[role]||navigation.employee,unread=visibleNotifications().filter(n=>!n.read).length;const name=role==='employee'?p.name:role==='manager'?'Тимур Асанов':role==='hr'?'Айнур Садыкова':'Администратор';const navItems=nav.map(([ico,label,url])=>`<a class="nav-item ${path===url||path.startsWith(url+'/')?'active':''}" href="#${url}" ${path===url?'aria-current="page"':''}>${icon(ico)}${label}${url==='/manager/reviews'?`<span class="count">${db.enrollments.filter(e=>e.employeeId==='E0028'&&e.status==='submitted').length}</span>`:''}</a>`).join('');return `<div class="app-shell"><div class="scrim ${menuOpen?'open':''}" data-action="close-menu"></div><aside class="sidebar ${menuOpen?'open':''}" aria-label="Основная навигация"><a class="brand" href="#${starts[role]}"><span class="brand-symbol">${icon('check')}</span>career quest<span class="sr-only"> · главная</span></a><button class="icon-button mobile-menu-close" data-action="close-menu" aria-label="Закрыть меню">${icon('close')}</button><div class="workspace-label"><span>A</span>Alem Team</div><div class="nav-caption">${role==='employee'?'Моё развитие':roleNames[role]}</div><nav class="nav-list">${navItems}</nav><div class="nav-bottom"><nav class="nav-list"><a class="nav-item ${path.startsWith('/app/settings')?'active':''}" href="#/app/settings">${icon('settings')}Настройки</a><a class="nav-item ${path==='/help'?'active':''}" href="#/help">${icon('help')}Помощь и поддержка</a></nav><div class="sidebar-footer"><a href="#/app/profile" class="avatar" aria-label="Открыть профиль">${initials(name)}</a><div class="user-copy"><strong>${esc(name.split(' ').slice(0,2).join(' '))}</strong><span>${roleNames[role]}</span></div><button class="icon-button" data-action="switch-role" aria-label="Сменить демо-роль">${icon('logout')}</button></div></div></aside><header class="topbar"><button class="icon-button mobile-toggle" data-action="menu" aria-label="Открыть меню" aria-expanded="${menuOpen}">${icon('menu')}</button><div class="breadcrumb"><a href="#${starts[role]}">Рабочее пространство</a>${icon('chevron')}<strong>${esc(titleFor(path))}</strong></div><div class="top-actions"><button class="demo-label" style="border:0;cursor:pointer" data-action="switch-role" title="Демоверсия · сменить роль">ДЕМО</button><button class="icon-button" data-action="search" aria-label="Поиск по продукту">${icon('search')}</button><a class="icon-button" href="#/app/notifications" aria-label="Уведомления${unread?', непрочитанных '+unread:''}">${icon('bell')}${unread?'<i class="notification-dot"></i>':''}</a><a class="avatar" href="#/app/profile" aria-label="Профиль">${initials(name)}</a></div></header><main id="main" class="main route-enter" tabindex="-1">${storageIssue?banner('Хранилище браузера недоступно. Изменения сохранятся только до закрытия этой страницы.','warning'):''}${content}<footer class="demo-footer"><span>Демоверсия · синтетические данные · изменения на этом устройстве</span><span><a href="#/privacy">Конфиденциальность</a> &nbsp;·&nbsp; <a href="#/accessibility">Доступность</a></span></footer></main><nav class="mobile-nav" aria-label="Мобильная навигация">${nav.slice(0,4).map(([ico,label,url])=>`<a class="${path===url?'active':''}" href="#${url}">${icon(ico)}<span>${label.replace('Каталог активностей','Каталог').replace('Карта навыков','Навыки').replace('Проверка результатов','Проверка').replace('Обзор программы','Обзор').replace('Мои активности','Активности').replace('Пользователи и роли','Пользователи')}</span></a>`).join('')}</nav></div>`;}
  function ring(p){return `<div class="ring" style="--value:${p.readiness}" role="img" aria-label="Готовность к ${esc(p.target)}: ${p.readiness}%"><div class="ring-inner"><span class="ring-value">${p.readiness}<small>%</small></span><span>готовность к грейду</span></div></div>`;}
  function skillBars(p){return p.skills.map(s=>`<div class="skill-item"><div class="skill-caption"><strong>${esc(s.name)}</strong><span>${s.level} / ${s.target} для ${esc(p.target)}</span></div><div class="progress ${s.level>=s.target?'green':''}"><span style="width:${Math.min(100,s.level/s.target*100)}%"></span></div></div>`).join('');}
  function home(){const p=person(),a=recommended(),ens=myEnrollments(),upcoming=ens.filter(e=>e.status==='enrolled'),verified=ens.filter(e=>e.status==='verified');return heading('Мой план развития',`Здравствуйте, ${esc(p.name.split(' ')[0])}. Сделаем следующий шаг к вашей цели.`,btn('Скачать план','export-plan','','download'),'ВАШЕ РАЗВИТИЕ, ВАШ ТЕМП')+`<div class="dashboard-top"><section class="card recommendation"><div class="rec-top">${tag('Рекомендуемый шаг','green','sparkles')}<span class="rec-score">${a?.score||94}% совпадение</span></div>${a?`<h2>${esc(a.title)}</h2><p>${esc(a.skill)} — ключевой навык для ${esc(p.target)}. Практика и обратная связь помогут увереннее применять его в работе.</p><div class="inline-meta"><span>${icon('book')}${esc(a.format)}</span><span>${icon('clock')}${a.hours} часов</span><span>${icon('calendar')}${date(a.date)}</span></div><div class="rec-footer">${link('Посмотреть активность','/app/activities/'+a.id,'primary','arrow')}${btn('Почему этот шаг?','explain','quiet')}</div>`:empty('Выберите следующий шаг','Изучите каталог доступных активностей.',link('В каталог','/app/catalog'))}</section><section class="card readiness"><div><div class="eyebrow">Карьерная цель</div><h2>${esc(p.role)}</h2><div class="grade-path">${esc(p.grade)}${icon('arrow')}<strong>${esc(p.target)}</strong></div></div>${ring(p)}<div class="readiness-foot"><span>${p.skills.filter(s=>s.level>=s.target).length} из ${p.skills.length} навыков на целевом уровне</span><a href="#/app/development-plan" aria-label="Посмотреть карту навыков">${icon('arrow')}</a></div></section></div><div class="grid three dashboard-stats">${stat(upcoming.length,'Предстоящих активностей','calendar','blue')}${stat(verified.length,'Подтверждённых результатов','check','lime')}${stat(ens.filter(e=>e.status==='submitted').length,'Результатов на проверке','clock','violet')}</div><div class="dashboard-bottom"><section class="card card-pad"><div class="section-head"><h2>Навыки для следующего грейда</h2>${textLink('Все навыки','/app/development-plan')}</div>${skillBars(p)}<p class="skill-note">Текущий уровень / целевой уровень. Прогресс обновляется после проверки.</p></section><section class="card card-pad"><div class="section-head"><h2>Ближайшие шаги</h2>${textLink('Мои активности','/app/enrollments')}</div>${upcoming.length?upcoming.slice(0,2).map(e=>activityRow(activity(e.activityId),'/app/enrollments/'+e.id,status(e.status))).join(''):catalog().slice(0,2).map(a=>activityRow(a,'/app/activities/'+a.id)).join('')}<a class="activity-row" href="#/app/development-plan"><div class="tile-icon violet">${icon('target')}</div><div class="activity-row-copy"><h3>Обсудите маршрут с руководителем</h3><p>Цели, практика и ожидания от следующего грейда</p></div>${icon('chevron')}</a></section></div><div class="callout">${icon('sparkles')}<p><strong>Не уверены, с чего начать?</strong> Навигатор объяснит рекомендацию и предложит альтернативы.</p>${textLink('Спросить навигатора','/app/navigator')}</div>`;}
  function activityRow(a,url,badge=''){if(!a)return '';return `<a class="activity-row" href="#${url}">${dateTile(a.date)}<div class="activity-row-copy"><h3>${esc(a.title)}</h3><p>${date(a.date)} · ${time(a.date)} · ${esc(a.format)}</p></div>${badge||icon('chevron')}</a>`;}
  function activityCard(a){return `<article class="card activity-card"><div class="activity-card-top"><div class="tile-icon ${a.color}">${icon(a.format==='Менторство'?'users':a.format==='Курс'?'book':a.format==='Проект'?'layers':'code')}</div>${a.id===person().recommended?tag('Для вашей цели','green','sparkles'):tag(a.skill)}</div><h2><a href="#/app/activities/${a.id}">${esc(a.title)}</a></h2><p class="description">${esc(a.description.split('. ')[0])}.</p><div class="inline-meta"><span>${icon('book')}${esc(a.format)}</span><span>${icon('clock')}${a.hours} ч</span><span>${icon('calendar')}${date(a.date,true)}</span></div><div class="activity-card-bottom"><span class="muted">${places(a)>0?places(a)+' мест доступно':'Лист ожидания'}</span>${textLink('Подробнее','/app/activities/'+a.id)}</div></article>`;}
  function places(a){return Math.max(0,a.capacity-a.booked-db.enrollments.filter(e=>e.activityId===a.id&&['enrolled','submitted','verified','revision'].includes(e.status)&&e.id!=='EN_DEMO_REVIEW').length);}
  function catalogPage(){const items=catalog().filter(a=>(!view.query||(a.title+' '+a.skill+' '+a.description).toLowerCase().includes(view.query.toLowerCase()))&&(view.format==='Все форматы'||a.format===view.format)&&(view.skill==='Все навыки'||a.skill===view.skill));return heading('Найдите свой следующий шаг','Активности, которые подходят вашей роли и помогают расти.',link('Мои активности','/app/enrollments','','calendar'))+`<div class="filters"><label class="search-field">${icon('search')}<span class="sr-only">Поиск активностей</span><input class="input" id="catalog-search" placeholder="Поиск по названию или навыку" value="${esc(view.query)}"></label><select aria-label="Формат активности" data-filter="format">${['Все форматы',...new Set(catalog().map(a=>a.format))].map(f=>`<option ${view.format===f?'selected':''}>${esc(f)}</option>`).join('')}</select><select aria-label="Навык" data-filter="skill">${['Все навыки',...new Set(catalog().map(a=>a.skill))].map(s=>`<option ${view.skill===s?'selected':''}>${esc(s)}</option>`).join('')}</select>${btn('Сбросить','reset-filters','quiet','refresh')}</div><div id="catalog-results"><div class="result-meta"><span>Доступно активностей: ${items.length}</span><span>Подобраны для ${esc(person().role)}</span></div>${items.length?`<div class="grid three">${items.map(activityCard).join('')}</div>`:`<div class="card">${empty('Ничего не найдено','Попробуйте другое название или сбросьте фильтры.',btn('Сбросить фильтры','reset-filters','primary'),'search')}</div>`}</div>`;}
  function detail(id){const a=activity(id);if(!a)return notFound();if(a.status!=='published'||!eligible(a))return forbidden('Эта активность недоступна для выбранного профиля.');const e=myEnrollments().find(e=>e.activityId===id&&e.status!=='cancelled');return heading('Активность',`${esc(a.format)} · ${esc(a.skill)}`,link('К каталогу','/app/catalog','','grid'))+`<div class="detail-layout"><div class="card"><section class="detail-hero"><div class="tile-icon ${a.color}">${icon('code')}</div><div class="inline-meta">${tag(a.format)}${tag(a.skill,'blue')}${a.id===person().recommended?tag('Рекомендуем для вашей цели','green','sparkles'):''}</div><h2 class="activity-title">${esc(a.title)}</h2><p>${esc(a.description)}</p></section><section class="detail-body"><h2>Что вы получите</h2><p>Примените ${esc(a.skill)} на конкретной задаче, получите обратную связь и сохраните результат в своём маршруте развития.</p>${banner('Ожидаемый эффект: <strong>+1 уровень навыка</strong> после проверки практической работы. Запись сама по себе не меняет прогресс.','success')}</section><section class="detail-body"><h2>Программа</h2><ol class="program">${a.program.map((s,i)=>`<li><span class="step-number">${String(i+1).padStart(2,'0')}</span>${esc(s)}</li>`).join('')}</ol></section><section class="detail-body"><h2>Как подтвердить результат</h2><p>После активности опишите, как применили навык, и при необходимости добавьте ссылку на работу. Руководитель проверит результат и даст обратную связь.</p></section><section class="detail-body"><h2>Ведущий</h2><div class="person"><span class="avatar">${initials(a.owner)}</span><div><strong>${esc(a.owner)}</strong><p>Практик и наставник · Alem Team</p></div></div></section></div><aside class="card booking-card"><h2>${e?'Ваша запись':'Присоединиться к активности'}</h2>${e?`<div style="margin-top:15px">${status(e.status)}</div>`:''}<div class="info-list">${infoLine('calendar','Дата и время',`${date(a.date)} · ${time(a.date)}`)}${infoLine('clock','Продолжительность',`${a.hours} часов · ${db.preferences.timezone}`)}${infoLine('pin','Формат участия',a.location)}${infoLine('users','Доступные места',`${places(a)} из ${a.capacity}`)}</div>${e?link('Открыть мою запись','/app/enrollments/'+e.id,'primary wide','arrow'):btn(places(a)?'Записаться':'Встать в лист ожидания','enroll','primary wide','plus',`data-id="${id}"`)}<p>Участие в рамках программы развития</p><div class="info-banner"><p>В демоверсии запись сохраняется на этом устройстве. Внешние уведомления не отправляются.</p></div><p>Отменить участие можно до начала активности.</p></aside></div>`;}
  function infoLine(ico,label,value){return `<div class="info-line">${icon(ico)}<div><span>${label}</span><strong>${esc(value)}</strong></div></div>`;}
  function enrollmentsPage(){const groups={all:'Все',active:'Предстоящие',review:'На проверке',completed:'Завершённые',cancelled:'Отменённые'},list=myEnrollments().filter(e=>view.tab==='all'||(view.tab==='active'&&['enrolled','waitlisted','revision'].includes(e.status))||(view.tab==='review'&&e.status==='submitted')||(view.tab==='completed'&&e.status==='verified')||(view.tab==='cancelled'&&e.status==='cancelled'));return heading('Мои активности','Записи, результаты и обратная связь — всё в одном месте.',link('Найти активность','/app/catalog','primary','plus'))+`<nav class="tabs" aria-label="Статус активности">${Object.entries(groups).map(([key,label])=>`<button class="tab ${view.tab===key?'active':''}" data-action="tab" data-tab="${key}" aria-pressed="${view.tab===key}">${label}</button>`).join('')}</nav>${list.length?`<div class="stack">${list.map(e=>{const a=activity(e.activityId);return `<article class="card card-pad"><div class="review-top"><div class="person"><div class="tile-icon ${a.color}">${icon('book')}</div><div><h2>${esc(a.title)}</h2><p class="small muted" style="margin-top:5px">${date(a.date)} · ${time(a.date)} · ${a.hours} ч</p></div></div>${status(e.status)}</div>${e.status==='revision'?banner(esc(e.reviewComment),'warning'):''}<div style="display:flex;justify-content:space-between;align-items:center;gap:15px;flex-wrap:wrap"><span class="small muted">${e.status==='submitted'?'Ожидаем обратную связь руководителя':e.status==='verified'?'Результат подтверждён и учтён в прогрессе':e.status==='waitlisted'?'Сообщим внутри демоверсии, если появится место':'Навык: '+esc(a.skill)}</span>${link(['enrolled','revision'].includes(e.status)?'Добавить результат':'Подробнее','/app/enrollments/'+e.id,'',e.status==='enrolled'?'upload':'arrow')}</div></article>`;}).join('')}</div>`:`<div class="card">${empty('Здесь появятся ваши активности','Выберите подходящий шаг в каталоге. После записи он появится на этой странице.',link('Выбрать активность','/app/catalog','primary','arrow'),'calendar')}</div>`}`;}
  function enrollmentDetail(id){const e=myEnrollments().find(e=>e.id===id);if(!e)return notFound();const a=activity(e.activityId);return heading('Моя запись',esc(a.title),link('Все активности','/app/enrollments','','calendar'))+`<div class="detail-layout"><div class="stack"><section class="card card-pad"><div class="section-head"><h2>${esc(a.title)}</h2>${status(e.status)}</div><div class="inline-meta"><span>${icon('calendar')}${date(a.date)} · ${time(a.date)}</span><span>${icon('clock')}${a.hours} часов</span></div><div class="timeline"><div class="timeline-step done"><span class="timeline-dot">${icon('check')}</span><h3>Запись ${e.status==='waitlisted'?'в лист ожидания':'создана'}</h3><p>${date(e.createdAt)}</p></div><div class="timeline-step ${['submitted','verified','revision'].includes(e.status)?'done':'current'}"><span class="timeline-dot">2</span><h3>Примените навык и поделитесь результатом</h3><p>Сохраните рабочий пример и кратко опишите свой вклад.</p></div><div class="timeline-step ${e.status==='verified'?'done':e.status==='submitted'?'current':''}"><span class="timeline-dot">${e.status==='verified'?icon('check'):'3'}</span><h3>Обратная связь руководителя</h3><p>${e.status==='verified'?'Результат подтверждён. Прогресс обновлён.':'После проверки результат появится в истории развития.'}</p></div></div></section>${e.reviewComment?`<section class="card card-pad"><h2>Обратная связь</h2><div class="review-evidence">${esc(e.reviewComment)}</div>${status(e.status)}</section>`:''}${['enrolled','revision'].includes(e.status)?`<section class="card card-pad"><h2>Подтверждение результата</h2><p class="small muted" style="margin-top:8px">Опишите задачу, ваше решение и полученный эффект.</p><form id="evidence-form" data-id="${id}" style="margin-top:22px"><div class="field"><label for="evidence">Что удалось применить?</label><textarea id="evidence" name="evidence" required minlength="20" maxlength="3000" placeholder="Например: спроектировала сервис уведомлений, описала компромиссы и получила ревью архитектуры…">${esc(e.evidence||'')}</textarea><small>Не менее 20 символов. Не добавляйте пароли и закрытую информацию.</small></div><div class="field" style="margin-top:20px"><label for="evidence-link">Ссылка на работу <span class="muted">(необязательно)</span></label><input class="input" id="evidence-link" name="link" type="url" placeholder="https://…" value="${esc(e.link||'')}"></div><label class="check-row" style="margin-top:20px"><input type="checkbox" name="consent" required>Я могу делиться этой работой с руководителем.</label><div class="form-actions"><button class="button primary" type="submit">${icon('send')}Отправить на проверку</button></div></form></section>`:e.evidence?`<section class="card card-pad"><h2>Отправленный результат</h2><div class="review-evidence">${esc(e.evidence)}</div>${e.link?safeLink(e.link,'Открыть работу'):''}</section>`:banner(e.status==='cancelled'?'Вы отменили участие. Можно выбрать другую активность в каталоге.':'Вы в листе ожидания. Отправка результата станет доступна после подтверждения места.')}</div><aside class="card booking-card"><h2>Детали участия</h2><div class="info-list">${infoLine('calendar','Дата',`${date(a.date)} · ${time(a.date)}`)}${infoLine('pin','Место',a.location)}${infoLine('user','Ведущий',a.owner)}</div>${btn('Добавить в календарь','calendar','wide','calendar',`data-id="${a.id}"`)}${['enrolled','waitlisted','revision'].includes(e.status)?`<div style="margin-top:12px">${btn('Отменить участие','cancel-enrollment','quiet wide','',`data-id="${e.id}"`)}</div>`:''}<div style="margin-top:20px">${textLink('Настройки напоминаний','/app/settings/notifications')}</div><div style="margin-top:16px"><a class="text-link" href="./telegram.html">${icon('send')}Подключение Telegram</a><p class="small muted" style="margin-top:10px">Для Telegram нужна отдельная серверная запись.</p></div></aside></div>`;}
  function safeLink(url,label){try{const parsed=new URL(url);if(!['https:','http:'].includes(parsed.protocol))return '';return `<a class="text-link" href="${esc(parsed.href)}" target="_blank" rel="noopener noreferrer">${esc(label)}${icon('external')}</a>`;}catch{return '';}}
  function developmentPlan(p=person(),manager=false){const a=recommended(p),events=db.progress.filter(e=>e.employeeId===p.id);return heading(manager?`Развитие: ${esc(p.name)}`:'Карта навыков',`${esc(p.role)} · ${esc(p.grade)} → ${esc(p.target)}`,manager?link(session.role==='manager'?'Моя команда':'Сотрудники',session.role==='manager'?'/manager/team':'/hr/people','','users'):btn('Скачать план','export-plan','','download'))+`<div class="card card-pad" style="margin-bottom:24px"><div class="section-head"><div><div class="eyebrow">Карьерная цель</div><h2>${esc(p.target)} ${esc(p.role)}</h2></div>${tag(p.readiness+'% готовности','blue','target')}</div><p class="small muted">${esc(p.goal)}</p><div class="progress" style="margin-top:22px"><span style="width:${p.readiness}%"></span></div></div><section class="card"><div class="table-heading section-head"><h2>Текущий уровень и цель</h2>${tag('Шкала 1–5')}</div><div class="table-wrap"><table class="data-table skill-table"><thead><tr><th>Навык</th><th>Ваш уровень</th><th>Цель</th><th>Следующий шаг</th></tr></thead><tbody>${p.skills.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td><div class="level-cells" aria-label="${s.level} из 5">${[1,2,3,4,5].map(n=>`<span class="${n<=s.level?'filled':n<=s.target?'target':''}"></span>`).join('')}</div><span class="small muted">${s.level} из 5</span></td><td>${s.target}</td><td>${s.level>=s.target?tag('Цель достигнута','green','check'):manager?tag('Развить ещё '+(s.target-s.level)+' ур.','blue'):`<a class="text-link" href="#/app/catalog?skill=${encodeURIComponent(s.name)}">Найти практику${icon('arrow')}</a>`}</td></tr>`).join('')}</tbody></table></div></section><div class="grid two" style="margin-top:24px"><section class="card card-pad"><h2>Маршрут к ${esc(p.target)}</h2><div class="timeline"><div class="timeline-step current"><span class="timeline-dot">1</span><h3>${esc(a?.title||'Выберите практическую активность')}</h3><p>Закрыть главный разрыв через практику</p>${a&&!manager?link('Посмотреть шаг','/app/activities/'+a.id,'','arrow'):''}</div><div class="timeline-step"><span class="timeline-dot">2</span><h3>Применить навык в рабочей задаче</h3><p>Сохранить результат и получить обратную связь руководителя.</p></div><div class="timeline-step"><span class="timeline-dot">3</span><h3>Обсудить готовность к новому грейду</h3><p>Опираясь на подтверждённые результаты, согласовать следующие цели.</p></div></div></section><section class="card card-pad"><div class="section-head"><h2>Подтверждённый прогресс</h2>${tag(events.length+' событий')}</div>${events.length?events.map(e=>`<div class="activity-row"><div class="tile-icon lime">${icon('check')}</div><div class="activity-row-copy"><h3>${esc(e.skill)} · ${e.before} → ${e.after}</h3><p>${date(e.date)} · подтверждено руководителем</p></div></div>`).join(''):empty('История только начинается','Подтверждённые руководителем результаты будут появляться здесь.','','route',true)}</section></div>${banner('Готовность — взвешенная доля закрытых требований: первые три навыка имеют веса 50%, 30% и 20%; для дополнительных навыков веса нормируются. Это ориентир для разговора, а решение о грейде принимает человек.')}`;}
  function navigatorPage(){if(!chat.length)chat.push({role:'assistant',text:`Здравствуйте, ${person().name.split(' ')[0]}! Я помогу разобраться в вашем маршруте. Ближайшая цель — ${person().target} ${person().role}. Рекомендую начать с «${recommended()?.title||'практической активности'}». Могу объяснить выбор, сравнить альтернативы или подсказать, как подтвердить результат.`});return heading('Ваш AI-навигатор','Понятные рекомендации с опорой на профиль и карту навыков.')+`<div class="chat-layout"><section class="card chat-card"><div id="chat-messages" class="chat-messages" aria-live="polite">${chat.map(m=>`<div class="chat-message ${m.role}">${m.role==='assistant'?`<span class="brand-symbol">${icon('sparkles')}</span>`:''}<div class="chat-bubble">${esc(m.text)}</div></div>`).join('')}</div><form id="chat-form" class="chat-input"><label for="chat-input" class="sr-only">Вопрос навигатору</label><input id="chat-input" class="input" name="prompt" placeholder="Спросите о своём развитии…" required maxlength="500" autocomplete="off"><button class="button primary" type="submit" aria-label="Отправить вопрос">${icon('send')}<span>Отправить</span></button></form></section><aside class="stack chat-side"><section class="card card-pad"><div class="section-head"><h2>С чего начать</h2></div><div class="prompt-list">${['Почему мне рекомендуют эту активность?','Какие есть альтернативы?','Что нужно для следующего грейда?','Как подтвердить результат?'].map(s=>`<button data-action="prompt" data-prompt="${s}">${s}</button>`).join('')}</div></section><section class="card card-pad"><h3>На чём основан ответ</h3><p class="small muted" style="margin-top:12px">Ваши навыки, целевой грейд и доступные активности.</p><p class="small muted" style="margin-top:12px">В демоверсии работает объяснимый сценарный помощник. Внешняя языковая модель не подключена.</p></section></aside></div>`;}
  function notificationsPage(){const list=visibleNotifications();return heading('Уведомления','Ответы руководителя и важные изменения в вашем маршруте.',btn('Отметить прочитанными','read-all','','check'))+`<div class="card">${list.length?list.map(n=>`<article class="notification ${!n.read?'unread':''}"><div class="tile-icon ${n.read?'':'blue'}">${icon('bell')}</div><div><a href="#${n.route}" data-read="${n.id}"><h3>${esc(n.title)}</h3><p>${esc(n.text)}</p></a></div><time>${date(n.date,true)}</time></article>`).join(''):empty('Вы ничего не пропустили','Здесь появятся ответы и изменения по вашим активностям.',link('Настроить уведомления','/app/settings/notifications'),'bell')}</div><div style="margin-top:20px">${textLink('Настроить уведомления','/app/settings/notifications')}</div>`;}
  function profilePage(){const p=person();if(session.role!=='employee')return heading('Профиль',roleNames[session.role])+`<div class="card card-pad"><div class="person"><span class="avatar large">${session.role==='manager'?'ТА':session.role==='hr'?'АС':'АД'}</span><div><h2>${session.role==='manager'?'Тимур Асанов':session.role==='hr'?'Айнур Садыкова':'Администратор платформы'}</h2><p>Демонстрационная роль · Alem Team</p></div></div>${banner('Переключение роли меняет демонстрационный интерфейс. Это не корпоративная авторизация.')}<div class="form-actions">${btn('Сменить роль','switch-role','primary','users')}</div></div>`;return heading('Мой профиль','Цель и предпочтения помогают подобрать полезный следующий шаг.',btn('Загрузить JSON','import-profile','','upload'))+`<form id="profile-form" class="card card-pad"><div class="person" style="margin-bottom:30px"><span class="avatar large">${initials(p.name)}</span><div><h2>${esc(p.name)}</h2><p class="small muted">${esc(p.team)} · ${Math.round(p.tenure/12)} года в компании</p></div></div><div class="form-grid"><div class="field"><label for="profile-name">Имя и фамилия</label><input class="input" id="profile-name" name="name" required maxlength="80" value="${esc(p.name)}"></div><div class="field"><label for="profile-email">Рабочая почта</label><input class="input" id="profile-email" name="email" type="email" required value="${esc(p.email)}"><small>Используется только в демопрофиле</small></div><div class="field"><label for="profile-role">Роль</label><input id="profile-role" class="input" value="${esc(p.role)}" disabled></div><div class="field"><label for="profile-target">Целевой грейд</label><select id="profile-target" name="target">${['Middle','Senior','Lead'].map(g=>`<option ${p.target===g?'selected':''}>${g}</option>`).join('')}</select></div><div class="field full"><label for="profile-goal">Моя цель развития</label><textarea id="profile-goal" name="goal" required maxlength="500">${esc(p.goal)}</textarea></div></div><div class="form-actions">${btn('Скачать профиль','export-profile','','download')}<button class="button primary" type="submit">${icon('check')}Сохранить изменения</button></div></form><div class="callout">${icon('shield')}<p>В демоверсии данные профиля хранятся в этом браузере. Используйте только синтетические данные.</p>${textLink('Подробнее','/privacy')}</div>`;}
  function toggle(key,label,desc){return `<label class="setting-row"><span><strong>${label}</strong><p>${desc}</p></span><input class="switch" type="checkbox" data-preference="${key}" ${db.preferences[key]?'checked':''} aria-label="${label}"></label>`;}
  function teamPage(hr=false){const team=hr?db.employees:db.employees.filter(p=>p.id==='E0028');const filtered=team.filter(p=>(p.name+' '+p.role+' '+p.team).toLowerCase().includes(view.query.toLowerCase()));return heading(hr?'Сотрудники':'Моя команда',hr?'Участники демонстрационной программы развития.':'Помогайте сотрудникам двигаться к их целям.',hr?btn('Экспорт','export-people','','download'):link('Проверить результаты','/manager/reviews','primary','check'))+`<div class="grid three" style="margin-bottom:26px">${stat(team.length,'Сотрудников','users','blue')}${stat(db.enrollments.filter(e=>team.some(p=>p.id===e.employeeId)&&e.status==='submitted').length,'Результатов на проверке','clock','violet')}${stat(db.progress.filter(e=>team.some(p=>p.id===e.employeeId)).length,'Подтверждённых шагов','check','lime')}</div><div class="filters"><label class="search-field">${icon('search')}<span class="sr-only">Поиск сотрудников</span><input class="input" id="people-search" value="${esc(view.query)}" placeholder="Имя, команда или роль"></label></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Сотрудник</th><th>Цель</th><th>Готовность</th><th>Активности</th><th></th></tr></thead><tbody>${filtered.map(p=>`<tr><td><div class="person"><span class="avatar">${initials(p.name)}</span><div><strong>${esc(p.name)}</strong><p>${esc(p.role)} · ${esc(p.team)}</p></div></div></td><td>${esc(p.grade)} → ${esc(p.target)}</td><td><div class="table-progress"><div class="progress"><span style="width:${p.readiness}%"></span></div>${p.readiness}%</div></td><td>${myEnrollments(p.id).filter(e=>e.status!=='cancelled').length}</td><td>${textLink('Открыть',hr?'/hr/people/'+p.id:'/manager/team/'+p.id)}</td></tr>`).join('')}</tbody></table>${!filtered.length?empty('Сотрудники не найдены','Измените поисковый запрос.',btn('Сбросить поиск','reset-filters'),'search'):''}</div>${banner(hr?'Показаны синтетические профили. Показатели рассчитаны по этой демовыборке.':'В демоверсии руководитель видит одного прямого подчинённого: Алию Нуржанову.')}`;}
  function reviewsPage(){const queue=db.enrollments.filter(e=>e.employeeId==='E0028'&&(view.tab==='history'?['verified','revision'].includes(e.status):e.status==='submitted'));return heading('Проверка результатов','Поддержите прогресс команды конкретной обратной связью.')+`<nav class="tabs" aria-label="Очередь результатов"><button class="tab ${view.tab!=='history'?'active':''}" data-action="tab" data-tab="all">Ожидают проверки <span class="count">${db.enrollments.filter(e=>e.employeeId==='E0028'&&e.status==='submitted').length}</span></button><button class="tab ${view.tab==='history'?'active':''}" data-action="tab" data-tab="history">История решений</button></nav>${queue.length?`<div class="stack">${queue.map(e=>{const p=db.employees.find(p=>p.id===e.employeeId),a=activity(e.activityId);return `<article class="card review-card"><div class="review-top"><div class="person"><span class="avatar">${initials(p.name)}</span><div><strong>${esc(p.name)}</strong><p>${esc(p.role)} · ${date(e.submittedAt||e.createdAt)}</p></div></div>${status(e.status)}</div><h2>${esc(a.title)}</h2><div class="review-evidence">${esc(e.evidence)}</div>${e.link?safeLink(e.link,'Открыть работу'):''}${e.status==='submitted'?`<form class="review-form" data-id="${e.id}"><div class="field"><label for="review-${e.id}">Обратная связь сотруднику</label><textarea id="review-${e.id}" name="comment" required minlength="10" maxlength="2000" placeholder="Что получилось хорошо? Что стоит доработать или применять дальше?"></textarea><small>Комментарий обязателен для обоих решений. Не менее 10 символов.</small></div><div class="review-actions"><button class="button" type="submit" name="decision" value="revision">Вернуть на доработку</button><button class="button primary" type="submit" name="decision" value="verified">${icon('check')}Подтвердить результат</button></div></form>`:banner(esc(e.reviewComment),e.status==='verified'?'success':'warning')}</article>`;}).join('')}</div>`:`<div class="card">${empty(view.tab==='history'?'Пока нет проверенных работ':'Все результаты проверены',view.tab==='history'?'Здесь будут храниться ваши решения и комментарии.':'Когда сотрудник отправит новую работу, она появится в этой очереди.',link('Открыть команду','/manager/team'),'check')}</div>`}`;}
  function hrOverview(analytics=false){const total=db.enrollments.filter(e=>e.status!=='cancelled').length,verified=db.enrollments.filter(e=>e.status==='verified').length;const skillGaps=Object.values(db.employees.flatMap(p=>p.skills).reduce((r,s)=>{if(s.level<s.target)r[s.name]={name:s.name,count:(r[s.name]?.count||0)+1};return r;},{})).sort((a,b)=>b.count-a.count);return heading(analytics?'Аналитика навыков':'Обзор программы развития',analytics?'Где командам нужна поддержка и какие шаги уже подтверждены.':'От потребности в навыке до подтверждённого результата.',btn('Скачать отчёт','export-analytics','','download'),'ALEM TEAM · ДЕМОДАННЫЕ')+`<div class="grid four" style="margin-bottom:26px">${stat(db.employees.length,'Участника программы','users','blue')}${stat(db.activities.filter(a=>a.status==='published').length,'Доступных активностей','grid','violet')}${stat(total,'Записей на активности','calendar','blue')}${stat(verified,'Подтверждённых результатов','check','lime')}</div><div class="grid two"><section class="card card-pad"><div class="section-head"><h2>Навыки, которым нужна поддержка</h2>${tag('Число сотрудников')}</div><div class="bar-chart">${skillGaps.map(s=>`<div class="chart-row"><span>${esc(s.name)}</span><div class="chart-bar" role="img" aria-label="${esc(s.name)}: ${s.count} сотрудников"><span style="width:${s.count/db.employees.length*100}%"></span></div><strong>${s.count}</strong></div>`).join('')}</div><p class="skill-note">Текущий уровень ниже цели · демовыборка из ${db.employees.length} сотрудников</p></section><section class="card card-pad"><div class="section-head"><h2>Путь от записи до результата</h2>${tag('Текущие статусы')}</div><div class="timeline">${[['enrolled','Участвуют'],['submitted','Ожидают проверки'],['revision','Дорабатывают результат'],['verified','Результат подтверждён']].map(([key,label],i)=>`<div class="timeline-step ${key==='verified'?'done':'current'}"><span class="timeline-dot">${i+1}</span><h3>${label}</h3><p>${db.enrollments.filter(e=>e.status===key).length} записей</p></div>`).join('')}</div></section></div>${!analytics?`<section class="card card-pad" style="margin-top:24px"><div class="section-head"><h2>Ближайшие активности</h2>${textLink('Управлять каталогом','/hr/activities')}</div>${db.activities.filter(a=>a.status==='published').slice(0,3).map(a=>activityRow(a,'/hr/activities/'+a.id,tag(places(a)+' свободных мест'))).join('')}</section>`:`<section class="card table-wrap" style="margin-top:24px"><div class="table-heading section-head"><h2>Данные по командам</h2></div><table class="data-table"><thead><tr><th>Команда</th><th>Участники</th><th>Записи</th><th>Подтверждено</th></tr></thead><tbody>${db.employees.map(p=>`<tr><td>${esc(p.team)}</td><td>1</td><td>${myEnrollments(p.id).filter(e=>e.status!=='cancelled').length}</td><td>${db.progress.filter(e=>e.employeeId===p.id).length}</td></tr>`).join('')}</tbody></table></section>`}${banner('Это аналитика синтетической демовыборки, а не оценка реальных сотрудников. Запись, посещение и подтверждённый навык — разные показатели.')}`;}
  function hrActivities(){const items=db.activities.filter(a=>(view.tab==='all'||a.status===view.tab)&&a.title.toLowerCase().includes(view.query.toLowerCase()));return heading('Программа активностей','Создавайте практику, которая помогает командам расти.',link('Создать активность','/hr/activities/new','primary','plus'))+`<nav class="tabs" aria-label="Статусы публикаций">${[['all','Все'],['published','Опубликованные'],['draft','Черновики'],['archived','Архив']].map(([k,v])=>`<button class="tab ${view.tab===k?'active':''}" data-action="tab" data-tab="${k}">${v}</button>`).join('')}</nav><div class="filters"><label class="search-field">${icon('search')}<span class="sr-only">Поиск активности</span><input class="input" id="hr-search" value="${esc(view.query)}" placeholder="Поиск по названию"></label></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Активность</th><th>Статус</th><th>Дата</th><th>Ведущий</th><th>Места</th><th></th></tr></thead><tbody>${items.map(a=>`<tr><td><strong>${esc(a.title)}</strong><p class="small muted">${esc(a.format)} · ${esc(a.skill)}</p></td><td>${status(a.status)}</td><td>${date(a.date,true)}</td><td>${esc(a.owner)}</td><td>${a.capacity-places(a)} / ${a.capacity}</td><td>${textLink('Управлять','/hr/activities/'+a.id)}</td></tr>`).join('')}</tbody></table>${!items.length?empty('В этом разделе пока пусто','Создайте активность или измените фильтры.',link('Создать активность','/hr/activities/new','primary'),'grid'):''}</div>`;}
  function activityEditor(id){const a=id?activity(id):null;if(id&&!a)return notFound();return heading(a?'Управление активностью':'Новая активность',a?esc(a.title):'Сначала сохраните черновик. Публикация — отдельный шаг.',link('Все активности','/hr/activities','','grid'))+`<div class="detail-layout"><div class="stack"><form id="activity-form" data-id="${a?.id||''}" class="card card-pad"><div class="section-head"><h2>Основная информация</h2>${a?status(a.status):status('draft')}</div><div class="form-grid"><div class="field full"><label for="activity-title">Название</label><input class="input" id="activity-title" name="title" required maxlength="120" value="${esc(a?.title||'')}" placeholder="Например: Практикум по системному дизайну"></div><div class="field full"><label for="activity-description">Описание и результат</label><textarea id="activity-description" name="description" required minlength="20" maxlength="1200">${esc(a?.description||'')}</textarea></div><div class="field"><label for="activity-format">Формат</label><select id="activity-format" name="format">${['Практикум','Менторство','Курс','Воркшоп','Проект'].map(f=>`<option ${a?.format===f?'selected':''}>${f}</option>`).join('')}</select></div><div class="field"><label for="activity-skill">Развиваемый навык</label><select id="activity-skill" name="skill">${db.skills.map(s=>`<option ${a?.skill===s.name?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label for="activity-date">Дата и время · UTC+5</label><input class="input" id="activity-date" type="datetime-local" name="date" required value="${a?new Date(new Date(a.date).getTime()+5*3600000).toISOString().slice(0,16):''}"></div><div class="field"><label for="activity-hours">Продолжительность, часов</label><input class="input" id="activity-hours" type="number" min="1" max="80" name="hours" required value="${a?.hours||2}"></div><div class="field"><label for="activity-capacity">Количество мест</label><input class="input" id="activity-capacity" type="number" name="capacity" required min="${a?Math.max(1,a.capacity-places(a)):1}" max="500" value="${a?.capacity||16}"></div><div class="field"><label for="activity-owner">Ведущий</label><input class="input" id="activity-owner" name="owner" required value="${esc(a?.owner||'')}"></div><div class="field full"><label for="activity-location">Место или формат участия</label><input class="input" id="activity-location" name="location" required value="${esc(a?.location||'Онлайн')}"></div><div class="field full"><span class="field-label">Аудитория</span><div class="audience-options">${['Backend Engineer','Data Analyst','Product Manager'].map(r=>`<label class="check-row"><input type="checkbox" name="audience" value="${r}" ${a?.roles.includes(r)?'checked':''}>${r}</label>`).join('')}</div><small>Если ничего не выбрано, активность доступна всем ролям.</small></div><div class="field full"><label for="activity-program">Программа · один пункт на строку</label><textarea id="activity-program" name="program" required>${esc(a?.program.join(String.fromCharCode(10))||'')}</textarea></div></div><div class="form-actions">${link('Отмена','/hr/activities')}<button type="submit" class="button primary">${icon('check')}${a?'Сохранить изменения':'Сохранить черновик'}</button></div></form>${a?roster(a):''}</div><aside class="card booking-card"><h2>Публикация</h2><p style="text-align:left;margin:18px 0">Проверьте программу, расписание и аудиторию перед публикацией.</p>${a?`${a.status!=='published'?btn(a.status==='archived'?'Опубликовать снова':'Опубликовать','publish','primary wide','check',`data-id="${a.id}"`):btn('Перенести в архив','archive','wide','',`data-id="${a.id}"`)}<div style="margin-top:12px">${btn('Предпросмотр','preview-activity','wide','external',`data-id="${a.id}"`)}</div>`:banner('Сохраните черновик, чтобы открыть предпросмотр и публикацию.')}<div style="margin-top:22px">${tag('Демоверсия','blue')}</div><p style="text-align:left">Изменения каталога видны в этой демоверсии на вашем устройстве.</p></aside></div>`;}
  function roster(a){const list=db.enrollments.filter(e=>e.activityId===a.id&&e.status!=='cancelled');return `<section class="card"><div class="table-heading section-head"><h2>Участники в демоверсии</h2>${tag(list.length+' записей')}</div>${list.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Сотрудник</th><th>Статус</th></tr></thead><tbody>${list.map(e=>`<tr><td>${esc(db.employees.find(p=>p.id===e.employeeId)?.name)}</td><td>${status(e.status)}</td></tr>`).join('')}</tbody></table></div>`:empty('Новых записей пока нет','После публикации сотрудники смогут записаться на эту активность.','','users',true)}<p class="skill-note" style="padding:0 24px 20px">Дополнительно ${a.booked} мест занято в исходном примере. Это не реальные участники.</p></section>`;}
  function adminPage(page){if(page==='overview')return heading('Обзор системы','Настройки демонстрационной среды и управление справочниками.')+`<div class="grid three" style="margin-bottom:26px">${stat(db.users.filter(u=>u.active).length,'Активных пользователей','users','blue')}${stat(db.skills.length,'Навыков в справочнике','layers','violet')}${stat(db.audit.length,'Действий в журнале','shield','lime')}</div><div class="grid two"><section class="card card-pad"><h2>Окружение</h2><div class="info-list">${infoLine('shield','Режим','Демонстрационный · синтетические данные')}${infoLine('file','Хранение','Локально в браузере')}${infoLine('users','Корпоративный вход','Не подключён')}${infoLine('send','Внешние уведомления','Не отправляются этим интерфейсом')}</div>${textLink('Интеграции','/admin/integrations')}</section><section class="card card-pad"><h2>Управление программой</h2><div class="prompt-list" style="margin-top:22px">${[['Пользователи и роли','/admin/users'],['Справочник навыков','/admin/skills'],['Матрицы требований','/admin/role-matrices'],['Журнал действий','/admin/audit-log']].map(([l,p])=>`<a class="button" href="#${p}" style="justify-content:space-between">${l}${icon('arrow')}</a>`).join('')}</div></section></div>`;
    if(page==='users'){const list=db.users.filter(u=>(u.name+' '+roleNames[u.role]).toLowerCase().includes(view.query.toLowerCase()));return heading('Пользователи и роли','Демонстрационные права доступа. Реальный SSO пока не подключён.')+`<div class="filters"><label class="search-field">${icon('search')}<span class="sr-only">Найти пользователя</span><input class="input" id="users-search" value="${esc(view.query)}" placeholder="Имя или роль"></label></div><div class="card table-wrap"><table class="data-table"><thead><tr><th>Пользователь</th><th>Роль</th><th>Статус</th><th>Действие</th></tr></thead><tbody>${list.map(u=>`<tr><td><div class="person"><span class="avatar blue">${initials(u.name)}</span><strong>${esc(u.name)}</strong></div></td><td>${roleNames[u.role]}</td><td>${tag(u.active?'Активен':'Приостановлен',u.active?'green':'')}</td><td>${btn('Изменить','edit-user','','edit',`data-id="${u.id}"`)}</td></tr>`).join('')}</tbody></table>${!list.length?empty('Пользователь не найден','Попробуйте другое имя или роль.',btn('Сбросить поиск','reset-filters'),'search'):''}</div>`;}
    if(page==='skills')return heading('Справочник навыков','Единые названия и понятные уровни развития.',btn('Добавить навык','add-skill','primary','plus'))+`<div class="card table-wrap"><table class="data-table"><thead><tr><th>Навык</th><th>Описание</th><th>Уровни</th><th></th></tr></thead><tbody>${db.skills.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td style="white-space:normal">${esc(s.description)}</td><td>1–5</td><td>${btn('Изменить','edit-skill','','edit',`data-id="${s.id}"`)}</td></tr>`).join('')}</tbody></table></div>`;
    if(page==='role-matrices'){const p=db.employees.find(p=>p.id===view.employee)||db.employees[0];return heading('Матрицы ролей','Требования к навыкам для целевого грейда.')+`<div class="filters"><select aria-label="Матрица роли" data-filter="employee">${db.employees.map(e=>`<option value="${e.id}" ${p.id===e.id?'selected':''}>${esc(e.role)} · ${esc(e.target)}</option>`).join('')}</select>${tag('Демонстрационная матрица','blue')}</div><form id="matrix-form" data-id="${p.id}" class="card card-pad"><div class="section-head"><h2>${esc(p.target)} ${esc(p.role)}</h2></div>${p.skills.map((s,i)=>`<div class="setting-row"><div><strong>${esc(s.name)}</strong><p>Требуемый уровень для роли</p></div><select name="skill-${i}" aria-label="Целевой уровень ${esc(s.name)}" style="width:90px">${[1,2,3,4,5].map(n=>`<option ${n===s.target?'selected':''}>${n}</option>`).join('')}</select></div>`).join('')}<div class="form-actions"><button class="button primary" type="submit">Сохранить матрицу</button></div></form>${banner('Изменение требований не подтверждает новые навыки. Решение фиксируется в локальном журнале.')}`;}
    if(page==='integrations')return heading('Интеграции','Статус подключений и требования к запуску.')+`<div class="grid two">${[['shield','Корпоративный SSO','OIDC / SAML','Вход через компанию требует сервера и настроенного поставщика идентификации.','sso'],['send','Telegram','Напоминания об активностях','Одноразовые ссылки и инструкция находятся в отдельном разделе подключения.','telegram'],['users','HRIS','Профили сотрудников','Синхронизация организационной структуры и профилей. Сейчас используются синтетические данные.','hris'],['book','LMS','Обучение и результаты','Импорт каталога обучения и подтверждённых результатов из системы компании.','lms']].map(([ico,title,sub,desc,key])=>`<section class="card card-pad"><div class="section-head"><div class="tile-icon blue">${icon(ico)}</div>${tag('Не подключено')}</div><h2>${title}</h2><p class="small muted" style="margin-top:5px">${sub}</p><p style="font-size:.875rem;line-height:1.8;margin:18px 0 22px">${desc}</p>${key==='telegram'?'<a class="button" href="./telegram.html">Открыть подключение</a>':btn('Что нужно для подключения','integration-info','','info',`data-id="${key}"`)}</section>`).join('')}</div>`;
    if(page==='audit-log'){const list=db.audit.filter(a=>(a.actor+' '+a.action+' '+a.object).toLowerCase().includes(view.query.toLowerCase()));return heading('Журнал действий','История изменений в этой демоверсии.',btn('Экспорт JSON','export-audit','','download'))+`<div class="filters"><label class="search-field">${icon('search')}<span class="sr-only">Поиск по журналу</span><input class="input" id="audit-search" value="${esc(view.query)}" placeholder="Действие, роль или объект"></label></div><div class="card table-wrap">${list.length?`<table class="data-table"><thead><tr><th>Когда</th><th>Кто</th><th>Действие</th><th>Объект</th></tr></thead><tbody>${list.map(a=>`<tr><td>${date(a.date,true)} · ${time(a.date)}</td><td>${esc(a.actor)}</td><td>${esc(a.action)}</td><td style="white-space:normal">${esc(a.object)}</td></tr>`).join('')}</tbody></table>`:empty('Пока нет действий','Изменения ролей, публикации активностей и решения по результатам появятся здесь.','','shield')}</div>${banner('Это локальный демонстрационный журнал. Защищённый аудит требует серверного хранения.')}`;}
    return notFound();
  }
  function publicShell(content){return `<div class="public-shell"><header class="public-header"><a class="brand" href="#/welcome"><span class="brand-symbol">${icon('check')}</span>career quest</a><nav><a href="#/privacy">Конфиденциальность</a>${link('Войти','/sign-in','','arrow')}</nav></header><main id="main" tabindex="-1">${content}</main></div>`;}
  function welcome(){return `<div class="landing"><div class="landing-hero"><div><div class="eyebrow">РАЗВИТИЕ, У КОТОРОГО ЕСТЬ НАПРАВЛЕНИЕ</div><h1>Следующий шаг.<br><span>С ясной целью.</span></h1><p>Соедините свои навыки, практику и обратную связь в понятный карьерный маршрут. Career Quest поможет увидеть, что делать дальше.</p><div class="page-tools">${link('Открыть рабочее пространство','/sign-in','primary','arrow')}</div><p class="small muted">Внутренний сервис развития сотрудников</p></div><section class="readiness"><div class="eyebrow">ВАША ЦЕЛЬ</div><h2>Senior Backend Engineer</h2>${ring(person())}<div class="readiness-foot"><span>Каждый подтверждённый шаг имеет значение</span>${icon('route')}</div></section></div><div class="grid three landing-steps">${[['01','Поймите свою цель','Увидьте текущие навыки и требования следующего грейда.'],['02','Выберите практику','Найдите активность, которая закрывает важный для вас разрыв.'],['03','Подтвердите результат','Примените навык и получите обратную связь руководителя.']].map(([n,t,d])=>`<section><span class="eyebrow">${n}</span><h3>${t}</h3><p>${d}</p></section>`).join('')}</div></div>`;}
  function signIn(){return `<div class="sign-in"><section class="sign-in-intro"><div class="eyebrow" style="color:#a6b2c7">CAREER QUEST / ALEM TEAM</div><h1>Ваше развитие.<br>В одной системе.</h1><p>От первого карьерного шага до подтверждённого результата — с понятным маршрутом и поддержкой команды.</p><div style="margin-top:40px">${tag('Демонстрационное пространство','dark','shield')}</div></section><section class="sign-in-form"><h2>Добро пожаловать</h2><p>Войдите через компанию или исследуйте продукт в деморежиме.</p>${btn('Войти через корпоративный аккаунт','sso','primary wide','shield')}<div class="divider-label">ПОСМОТРЕТЬ ДЕМОВЕРСИЮ</div>${[['employee','user','Сотрудник','Мой маршрут, навыки и активности'],['manager','users','Руководитель','Команда и проверка результатов'],['hr','chart','HR-партнёр','Программа развития и аналитика'],['admin','settings','Администратор','Пользователи, роли и справочники']].map(([key,ico,label,desc])=>`<button class="role-choice" data-action="enter-role" data-role="${key}"><span class="tile-icon ${key==='employee'?'lime':'blue'}">${icon(ico)}</span><span><strong>${label}</strong><small>${desc}</small></span>${icon('chevron')}</button>`).join('')}<p style="font-size:.6875rem;margin-top:24px;margin-bottom:0">Демороли используют синтетические данные. Это не вход в корпоративную систему.</p></section></div>`;}
  function onboarding(){return `<form id="onboarding-form" class="card onboarding"><span class="tile-icon lime">${icon('target')}</span><h1>Куда вы хотите расти?</h1><p>Достаточно цели и роли. Остальное можно уточнить позже.</p><div class="field"><label for="onboarding-person">Ваш демопрофиль</label><select id="onboarding-person" name="profile">${db.employees.map(p=>`<option value="${p.id}" ${p.id===db.profile?'selected':''}>${esc(p.name)} · ${esc(p.role)}</option>`).join('')}</select></div><div class="field"><label for="onboarding-target">Целевой грейд</label><select id="onboarding-target" name="target"><option>Middle</option><option selected>Senior</option><option>Lead</option></select></div><button class="button primary wide" type="submit">Показать мой маршрут${icon('arrow')}</button><p style="font-size:.75rem;text-align:center;margin:16px 0 0">Цель можно изменить в профиле в любой момент.</p></form>`;}
  function helpPage(){return heading('Помощь и поддержка','Ответы на вопросы о вашем маршруте развития.')+`<div class="grid two"><section class="card card-pad faq"><h2>Как всё устроено</h2>${[['Как строится рекомендация?','Учитываются разрыв между текущим и целевым уровнем навыка, его важность для роли, ожидаемый эффект активности, соответствие роли и формату. В демоверсии рекомендации сценарные, а не ответы внешнего AI.'],['Почему готовность не выросла после записи?','Запись — начало пути. Уровень навыка обновляется после практической работы и подтверждения результата руководителем.'],['Как отменить участие?','Откройте «Мои активности», выберите запись и нажмите «Отменить участие». Отмена доступна до начала активности.'],['Как проверить результат от лица руководителя?','Нажмите метку «ДЕМО», выберите роль руководителя и откройте «Проверка результатов». Добавьте конкретный комментарий и подтвердите работу или верните её на доработку.'],['Почему мои изменения не видны коллегам?','Эта версия сохраняет демоданные в вашем браузере. Для совместной работы нужна корпоративная версия с сервером и SSO.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><div class="stack"><section class="card card-pad"><div class="tile-icon blue" style="margin-bottom:20px">${icon('send')}</div><h2>Telegram-напоминания</h2><p style="font-size:.875rem;margin:15px 0 22px">Получите одноразовую ссылку для серверной записи и подключите бот по инструкции.</p><a href="./telegram.html" class="button">Открыть инструкцию${icon('arrow')}</a></section><section class="card card-pad"><h2>Изучить интерфейс</h2><p class="small muted" style="margin:15px 0 22px">Переключайтесь между четырьмя ролями, чтобы пройти весь путь развития.</p>${btn('Сменить демо-роль','switch-role','','users')}<div style="margin-top:18px">${textLink('Состояния интерфейса','/design-system')}</div></section></div></div>`;}
  function policyPage(kind){return `<article class="prose card card-pad"><div class="eyebrow">CAREER QUEST / ДЕМОВЕРСИЯ</div><h1>${kind==='privacy'?'Конфиденциальность':'Доступность интерфейса'}</h1>${kind==='privacy'?`<h2>Какие данные используются</h2><p>В приложении используются синтетические профили сотрудников, навыки, карьерные цели, записи на активности и тексты демонстрационных результатов. Не вводите персональные данные реальных людей или конфиденциальные рабочие материалы.</p><h2>Где хранятся изменения</h2><p>Демоданные сохраняются в localStorage этого браузера и остаются до очистки данных сайта или сброса демоверсии в настройках. Эта оболочка не отправляет профиль и результаты во внешнюю AI-модель. Google Fonts может получать технические данные запроса шрифта.</p><h2>Telegram и серверный MVP</h2><p>Подключение Telegram — отдельный добровольный сценарий. Он использует серверные записи и одноразовую ссылку. Перед подключением ознакомьтесь с инструкцией и статусом сервера.</p><h2>Ваш контроль</h2><p>Профиль и маршрут можно экспортировать. Все изменения демоверсии можно сбросить в разделе «Настройки → Данные и приватность». Для корпоративного запуска компания должна отдельно определить правовые основания, сроки хранения и ответственного за данные.</p>`:`<h2>Управление без мыши</h2><p>Переходите между действиями клавишей Tab и активируйте их клавишей Enter. Диалоги закрываются клавишей Escape. Ссылка в начале страницы позволяет сразу перейти к содержимому.</p><h2>Чтение и движение</h2><p>Интерфейс адаптируется к размеру экрана, поддерживает увеличение текста, светлую и тёмную темы. Состояния сопровождаются текстовыми подписями. Уменьшение движения учитывает настройки устройства и приложения.</p><h2>Границы проверки</h2><p>Доступность предусмотрена в компонентах интерфейса. Это не заявление о независимой сертификации. Перед корпоративным запуском необходима проверка со скринридерами и участием пользователей.</p>`}<div style="margin-top:30px">${link('Вернуться в приложение',starts[session?.role]||'/sign-in','','arrow')}</div></article>`;}
  function statesPage(){return heading('Состояния интерфейса','Общие компоненты и обратная связь Career Quest.')+`<div class="grid two states-grid"><section class="card"><div class="state-caption">Пустое состояние</div>${empty('Пока нет активностей','Найдите первый шаг в каталоге.',link('Открыть каталог','/app/catalog','primary'),'calendar',true)}</section><section class="card"><div class="state-caption">Загрузка</div><div class="skeleton-card" aria-label="Загрузка данных"><div class="skeleton" style="width:35%"></div><div class="skeleton" style="height:45px;width:75%"></div><div class="skeleton" style="width:90%"></div><div class="skeleton" style="width:60%"></div></div></section><section class="card card-pad"><h2>Не удалось загрузить данные</h2><p class="small muted" style="margin:15px 0 22px">Проверьте подключение и попробуйте ещё раз. Ваши изменения сохранены на устройстве.</p>${btn('Повторить','retry-demo','','refresh')}</section><section class="card card-pad"><h2>Результат отправлен</h2>${banner('Руководитель получил вашу работу. Ответ появится в уведомлениях.','success')}<div class="page-tools">${status('submitted')}${status('verified')}</div></section><section class="card card-pad"><h2>Кнопки</h2><div class="page-tools" style="margin-top:22px;flex-wrap:wrap">${btn('Основное действие','sample-toast','primary')}${btn('Вторичное','sample-toast')}${btn('Недоступно','sample-toast','','','disabled')}</div></section><section class="card card-pad"><h2>Подтверждение действия</h2><p class="small muted" style="margin:15px 0 22px">Критичное действие требует явного выбора, а отмена возвращает в исходный контекст.</p>${btn('Открыть пример','sample-confirm','','info')}</section></div>`;}
  function notFound(){return `<div class="card">${empty('<span class="error-code">404</span><br>Страница не найдена','Возможно, адрес изменился или запись больше недоступна.',link('На главную',starts[session?.role]||'/sign-in','primary','arrow'),'search')}</div>`;}
  function forbidden(text='У выбранной демороли нет доступа к этому разделу.'){return `<div class="card">${empty('Этот раздел для другой роли',text,btn('Выбрать демо-роль','switch-role','primary','users'),'shield')}</div>`;}
  function render(){
    const raw=location.hash.slice(1)||(session?.role?starts[session.role]:'/sign-in'),path=raw.split('?')[0],params=new URLSearchParams(raw.split('?')[1]||'');
    const changed=activeRoute!==path;
    if(changed){view={query:'',format:'Все форматы',skill:params.get('skill')||'Все навыки',tab:'all'};menuOpen=false;}
    activeRoute=path;document.body.dataset.theme=db.preferences.theme;document.body.classList.toggle('reduce-motion',db.preferences.reducedMotion);
    let html='',isPublic=['/welcome','/sign-in','/onboarding','/privacy','/accessibility'].includes(path);
    if(!session?.role&&!isPublic){go('/sign-in');return;}
    if(path==='/welcome')html=welcome();else if(path==='/sign-in')html=signIn();else if(path==='/onboarding')html=onboarding();else if(path==='/privacy'||path==='/accessibility')html=policyPage(path.slice(1));
    else if((path.startsWith('/manager/')&&session.role!=='manager')||(path.startsWith('/hr/')&&!['hr','admin'].includes(session.role))||(path.startsWith('/admin/')&&session.role!=='admin'))html=forbidden();
    else if(path==='/app/home')html=session.role==='employee'?home():forbidden();
    else if(path==='/app/catalog')html=session.role==='employee'?catalogPage():forbidden();
    else if(path.startsWith('/app/activities/'))html=session.role==='employee'?detail(path.split('/')[3]):forbidden();
    else if(path==='/app/enrollments')html=session.role==='employee'?enrollmentsPage():forbidden();
    else if(path.startsWith('/app/enrollments/'))html=session.role==='employee'?enrollmentDetail(path.split('/')[3]):forbidden();
    else if(path==='/app/development-plan')html=session.role==='employee'?developmentPlan():forbidden();
    else if(path==='/app/navigator')html=session.role==='employee'?navigatorPage():forbidden();
    else if(path==='/app/notifications')html=notificationsPage();
    else if(path==='/app/profile')html=profilePage();
    else if(path.startsWith('/app/settings'))html=settingsPage(path.split('/')[3]||'general');
    else if(path==='/manager/team')html=teamPage();
    else if(path.startsWith('/manager/team/'))html=path.split('/')[3]==='E0028'?developmentPlan(db.employees.find(p=>p.id==='E0028'),true):forbidden('Этот сотрудник не входит в вашу команду.');
    else if(path==='/manager/reviews')html=reviewsPage();
    else if(path==='/hr/overview'||path==='/hr/analytics')html=hrOverview(path.endsWith('analytics'));
    else if(path==='/hr/people')html=teamPage(true);
    else if(path.startsWith('/hr/people/')){const p=db.employees.find(e=>e.id===path.split('/')[3]);html=p?developmentPlan(p,true):notFound();}
    else if(path==='/hr/activities')html=hrActivities();
    else if(path.startsWith('/hr/activities/'))html=activityEditor(path.endsWith('/new')?null:path.split('/')[3]);
    else if(path.startsWith('/admin/'))html=adminPage(path.split('/')[2]);
    else if(path==='/help')html=helpPage();else if(path==='/design-system')html=statesPage();else html=notFound();
    app.innerHTML=isPublic?publicShell(html):shell(html,path);
    const sidebar=app.querySelector('.sidebar');if(sidebar)sidebar.inert=window.innerWidth<=800&&!menuOpen;
    if(menuOpen){app.querySelector('.main').inert=true;app.querySelector('.topbar').inert=true;app.querySelector('.mobile-nav').inert=true;app.querySelector('.mobile-menu-close')?.focus();}
    document.title=(document.querySelector('h1')?.textContent||titleFor(path))+' — Career Quest';
    if(changed){window.scrollTo(0,0);if(location.hash)document.querySelector('#main h1,#main')?.focus({preventScroll:true});}
  }
  function openDialog(title,body,actions=''){lastFocus=document.activeElement;dialog.innerHTML=`<button class="icon-button dialog-close" data-action="close-dialog" aria-label="Закрыть">${icon('close')}</button><div class="dialog-body"><h2 class="dialog-heading" id="dialog-title">${title}</h2>${body}${actions?`<div class="dialog-actions">${actions}</div>`:''}</div>`;if(!dialog.open)dialog.showModal();}
  function closeDialog(){dialog.close();if(lastFocus?.isConnected)lastFocus.focus();}
  dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
  dialog.addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();});
  function formError(form,text){let error=form.querySelector('.form-error');if(!error){error=document.createElement('div');error.className='form-error';error.setAttribute('role','alert');form.prepend(error);}error.textContent=text;error.scrollIntoView({block:'center',behavior:'smooth'});}
  function askNavigator(prompt){if(!prompt.trim())return;const p=person(),a=recommended(),gap=p.skills.filter(s=>s.level<s.target).sort((a,b)=>(b.target-b.level)-(a.target-a.level))[0];let answer='Я могу объяснить рекомендации, подобрать альтернативу, показать требования к грейду и помочь с подтверждением результата. Сформулируйте вопрос об одном из этих шагов.';if(/почему|рекомен|начать/i.test(prompt))answer=`Рекомендую «${a?.title}»: навык ${a?.skill} связан с вашей целью ${p.target}. ${gap?`Самый заметный разрыв — ${gap.name}: сейчас ${gap.level}, нужно ${gap.target}.`:''} Совпадение ${a?.score}% — демонстрационная оценка соответствия. После практики отправьте результат руководителю; только его подтверждение меняет навык.`;if(/альтернатив|друг|формат/i.test(prompt))answer='Подходящие варианты: '+catalog().filter(x=>x.id!==a?.id).slice(0,3).map(x=>`«${x.title}» (${x.format.toLowerCase()}, ${x.hours} ч)`).join('; ')+'. Все варианты доступны в каталоге. Выбирайте формат, в котором легче применить навык на практике.';if(/грейд|Senior|Middle|цель|нужно/i.test(prompt))answer=`Ваша цель — ${p.target} ${p.role}. Навыки для развития: ${p.skills.filter(s=>s.level<s.target).map(s=>`${s.name} ${s.level} → ${s.target}`).join(', ')||'текущие требования закрыты'}. Текущая готовность: ${p.readiness}%. Обсудите с руководителем рабочую задачу, на которой сможете показать результат. Процент не является решением о повышении.`;if(/подтверд|результат|провер|evidence/i.test(prompt))answer='Откройте «Мои активности» и нужную запись. Опишите задачу, ваше решение и эффект, затем добавьте ссылку на работу при необходимости. Отправьте результат на проверку. Руководитель подтвердит его или оставит конкретный комментарий для доработки.';chat.push({role:'user',text:prompt},{role:'assistant',text:answer});render();const el=document.getElementById('chat-messages');if(el)el.scrollTop=el.scrollHeight;document.getElementById('chat-input')?.focus();}
  function exportFile(name,content,type='application/json'){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function csv(rows){return '\uFEFF'+rows.map(row=>row.map(v=>{let s=String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}).join(',')).join(String.fromCharCode(13,10));}
  function calendarExport(id){const a=activity(id);if(!a)return;const stamp=v=>new Date(v).toISOString().replaceAll('-','').replaceAll(':','').split('.')[0]+'Z';const clean=v=>String(v).replaceAll(String.fromCharCode(10),' ').replaceAll(',',' ').replaceAll(';',' ');const text=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Career Quest//Demo//RU','BEGIN:VEVENT','UID:'+a.id+'@careerquest.demo','DTSTAMP:'+stamp(new Date()),'DTSTART:'+stamp(a.date),'DTEND:'+stamp(new Date(new Date(a.date).getTime()+a.hours*3600000)),'SUMMARY:'+clean(a.title),'DESCRIPTION:'+clean(a.description),'LOCATION:'+clean(a.location),'END:VEVENT','END:VCALENDAR'].join(String.fromCharCode(13,10));exportFile('career-quest-'+id+'.ics',text,'text/calendar;charset=utf-8');toast('Файл календаря скачан');}
  function confirmEnrollment(id){const a=activity(id);if(session?.role!=='employee'||!a||a.status!=='published'||!eligible(a))return toast('Активность недоступна для этого профиля.');if(new Date(a.date)<=new Date())return toast('Запись закрыта: активность уже началась.');const existing=myEnrollments().find(e=>e.activityId===id&&e.status!=='cancelled');if(existing){closeDialog();go('/app/enrollments/'+existing.id);return;}const state=places(a)>0?'enrolled':'waitlisted',e={id:'EN_'+crypto.randomUUID(),activityId:id,employeeId:person().id,status:state,createdAt:new Date().toISOString()};db.enrollments.unshift(e);audit(state==='enrolled'?'Запись на активность':'Запись в лист ожидания',a.title);notify(state==='enrolled'?'Вы записаны на активность':'Вы в листе ожидания',a.title,'/app/enrollments/'+e.id);save();closeDialog();go('/app/enrollments/'+e.id);toast(state==='enrolled'?'Запись создана. Добавьте активность в календарь.':'Вы добавлены в лист ожидания.');}
  function searchDialog(){openDialog('Поиск по Career Quest',`<label class="search-field" style="display:block;margin-top:20px">${icon('search')}<span class="sr-only">Поиск страниц и активностей</span><input id="global-search" class="input" autofocus placeholder="Страница, активность или навык"></label><div id="global-results" class="search-results"></div>`);searchResults('');setTimeout(()=>document.getElementById('global-search')?.focus(),0);}
  function searchResults(query){const pages=[...(navigation[session?.role]||navigation.employee).map(([ico,name,url])=>({name,url,type:'Страница'})),{name:'Настройки уведомлений',url:'/app/settings/notifications',type:'Настройки'},{name:'Профиль',url:'/app/profile',type:'Страница'},{name:'Помощь',url:'/help',type:'Страница'},...(session?.role==='employee'?catalog().map(a=>({name:a.title,url:'/app/activities/'+a.id,type:a.skill})):[])].filter(x=>(x.name+' '+x.type).toLowerCase().includes(query.toLowerCase())).slice(0,10);document.getElementById('global-results').innerHTML=pages.length?pages.map(p=>`<a class="search-result" href="#${p.url}" data-action="close-dialog"><span>${esc(p.name)}<small>${esc(p.type)}</small></span>${icon('arrow')}</a>`).join(''):empty('Ничего не найдено','Попробуйте другое название.','','search',true);}
  document.addEventListener('click',event=>{
    if(event.target.closest('.skip-link')){event.preventDefault();document.getElementById('main')?.focus();return;}
    const readTarget=event.target.closest('[data-read]');if(readTarget){const n=db.notifications.find(n=>n.id===readTarget.dataset.read);if(n){n.read=true;save();}}
    const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action,id=target.dataset.id;
    if(action==='menu'||action==='close-menu'){menuOpen=action==='menu'?!menuOpen:false;render();if(!menuOpen)document.querySelector('.mobile-toggle')?.focus();return;}
    if(action==='close-dialog')return closeDialog();
    if(action==='switch-role'){go('/sign-in');return;}
    if(action==='enter-role'){session={role:target.dataset.role};save();go(session.role==='employee'&&!db.onboarded?'/onboarding':starts[session.role]);return;}
    if(action==='sso'){openDialog('Корпоративный вход пока не настроен','<p>Для входа через компанию нужен подключённый поставщик SSO. Пока можно изучить весь продукт с синтетическими данными, выбрав одну из деморолей.</p>',btn('Понятно','close-dialog','primary'));return;}
    if(action==='search')return searchDialog();
    if(action==='tab'){view.tab=target.dataset.tab;render();return;}
    if(action==='reset-filters'){view={query:'',format:'Все форматы',skill:'Все навыки',tab:'all'};render();return;}
    if(action==='explain'){const a=recommended(),s=person().skills.find(s=>s.name===a.skill);openDialog('Почему именно этот шаг?',`<p>Рекомендация «${esc(a.title)}» связана с вашей целью — ${esc(person().target)} ${esc(person().role)}.</p><div class="info-list">${infoLine('target','Разрыв навыка',s?`${s.name}: сейчас ${s.level}, цель ${s.target}`:a.skill)}${infoLine('users','Соответствие роли',person().role)}${infoLine('book','Подходящий формат',`${a.format} · ${a.hours} часов`)}</div>${banner('Совпадение '+a.score+'% — демонстрационная оценка, а не гарантия результата. Навык подтверждается после практики и проверки.')}`,link('Открыть активность','/app/activities/'+a.id,'primary','arrow'));dialog.querySelector('a')?.addEventListener('click',closeDialog);return;}
    if(action==='enroll'){const a=activity(id);openDialog(places(a)?'Записаться на активность?':'Встать в лист ожидания?',`<p><strong>${esc(a.title)}</strong></p><div class="info-list">${infoLine('calendar','Дата и время',date(a.date)+' · '+time(a.date)+' · '+db.preferences.timezone)}${infoLine('clock','Продолжительность',a.hours+' часов')}</div>${banner('Это демозапись на вашем устройстве. Она не отправляет сообщения и не создаёт реальную заявку.')}`,btn('Отмена','close-dialog')+btn(places(a)?'Подтвердить запись':'Добавить в ожидание','confirm-enroll','primary','check',`data-id="${id}"`));return;}
    if(action==='confirm-enroll')return confirmEnrollment(id);
    if(action==='calendar')return calendarExport(id);
    if(action==='cancel-enrollment'){const e=myEnrollments().find(e=>e.id===id);if(!e)return;const a=activity(e.activityId);if(new Date(a.date)<=new Date())return toast('Самостоятельная отмена закрыта: активность уже началась.');openDialog('Отменить участие?',`<p>Запись на «${esc(a.title)}» перейдёт в историю. При наличии мест можно будет записаться снова.</p>`,btn('Оставить запись','close-dialog')+btn('Отменить участие','confirm-cancel','danger','',`data-id="${id}"`));return;}
    if(action==='confirm-cancel'){const e=myEnrollments().find(e=>e.id===id);if(e&&['enrolled','waitlisted','revision'].includes(e.status)){e.status='cancelled';promoteWaitlist(e.activityId);audit('Отмена записи',activity(e.activityId).title);save();closeDialog();render();toast('Участие отменено');}return;}
    if(action==='read-all'){visibleNotifications().forEach(n=>n.read=true);save();render();toast('Все уведомления прочитаны');return;}
    if(action==='prompt'){askNavigator(target.dataset.prompt);return;}
    if(action==='export-plan'||action==='export-profile'){exportFile('career-quest-'+(action==='export-plan'?'plan':'profile')+'.json',JSON.stringify({profile:person(),activities:myEnrollments(),progress:db.progress.filter(p=>p.employeeId===person().id),demo:true},null,2));toast('Файл скачан');return;}
    if(action==='export-people'||action==='export-analytics'){if(!['hr','admin'].includes(session.role))return;const rows=action==='export-people'?[['Имя','Роль','Грейд','Цель','Готовность'],...db.employees.map(p=>[p.name,p.role,p.grade,p.target,p.readiness])]:[['Показатель','Значение'],['Синтетических сотрудников',db.employees.length],['Активностей',db.activities.length],['Записей',db.enrollments.filter(e=>e.status!=='cancelled').length],['Подтверждённых результатов',db.progress.length]];audit('Экспорт демоотчёта',action==='export-people'?'Сотрудники':'Аналитика');save();exportFile('career-quest-demo-report.csv',csv(rows),'text/csv;charset=utf-8');toast('Отчёт скачан');return;}
    if(action==='export-audit'){exportFile('career-quest-audit-demo.json',JSON.stringify(db.audit,null,2));return;}
    if(action==='import-profile'){openDialog('Загрузить демопрофиль','<p>Выберите JSON с полями employee_id, role, grade, tenure_months и skills. Уровни навыков — числа от 1 до 5. Используйте только синтетические данные.</p><form id="import-form"><div class="field"><label for="profile-file">JSON-файл до 100 КБ</label><input class="input" id="profile-file" type="file" name="file" accept="application/json,.json" required></div><div class="dialog-actions"><button class="button primary" type="submit">Загрузить профиль</button></div></form>');return;}
    if(action==='publish'||action==='archive'){if(!['hr','admin'].includes(session.role))return;const a=activity(id);openDialog(action==='publish'?'Опубликовать активность?':'Перенести в архив?',`<p>${action==='publish'?'Активность станет доступна подходящим демопрофилям. Проверьте сохранённые дату, аудиторию и программу.':'Новые записи будут закрыты. Существующие записи и результаты сохранятся.'}</p><p><strong>${esc(a.title)}</strong></p>`,btn('Отмена','close-dialog')+btn(action==='publish'?'Опубликовать':'В архив','confirm-publication','primary','',`data-id="${id}" data-status="${action==='publish'?'published':'archived'}"`));return;}
    if(action==='confirm-publication'){if(!['hr','admin'].includes(session.role))return;const a=activity(id);if(target.dataset.status==='published'&&new Date(a.date)<=new Date())return toast('Укажите будущую дату перед публикацией.');a.status=target.dataset.status;a.publishedAt=new Date().toISOString();audit(a.status==='published'?'Публикация активности':'Архивация активности',a.title);save();closeDialog();render();toast(a.status==='published'?'Активность опубликована':'Активность в архиве');return;}
    if(action==='preview-activity'){const a=activity(id);openDialog(esc(a.title),`<p>${esc(a.description)}</p><div class="info-list">${infoLine('calendar','Дата',date(a.date)+' · '+time(a.date))}${infoLine('users','Аудитория',a.roles.join(', ')||'Все роли')}${infoLine('book','Навык',a.skill)}</div><ol class="program">${a.program.map((s,i)=>`<li><span class="step-number">${i+1}</span>${esc(s)}</li>`).join('')}</ol>`,btn('Закрыть','close-dialog','primary'));return;}
    if(action==='edit-user'){if(session.role!=='admin')return;const u=db.users.find(u=>u.id===id);openDialog('Изменить демопользователя',`<p>${esc(u.name)}</p><form id="user-form" data-id="${id}"><div class="field"><label for="user-role">Роль</label><select id="user-role" name="role">${Object.entries(roleNames).map(([k,v])=>`<option value="${k}" ${u.role===k?'selected':''}>${v}</option>`).join('')}</select></div><label class="setting-row"><strong>Доступ активен</strong><input name="active" class="switch" type="checkbox" ${u.active?'checked':''} aria-label="Доступ активен"></label>${banner('Изменение относится к демонстрационному справочнику. Реальные права определяет сервер компании.')}<div class="dialog-actions"><button class="button primary" type="submit">Сохранить</button></div></form>`);return;}
    if(action==='add-skill'||action==='edit-skill'){if(session.role!=='admin')return;const s=db.skills.find(s=>s.id===id);openDialog(s?'Редактировать навык':'Новый навык',`<form id="skill-form" data-id="${s?.id||''}"><div class="field"><label for="skill-name">Название навыка</label><input class="input" id="skill-name" name="name" required maxlength="80" value="${esc(s?.name||'')}"></div><div class="field"><label for="skill-description">Описание уровней</label><textarea id="skill-description" name="description" required maxlength="500">${esc(s?.description||'')}</textarea></div><div class="dialog-actions"><button class="button primary" type="submit">Сохранить навык</button></div></form>`);return;}
    if(action==='integration-info'){const details={sso:'Для корпоративного входа нужны OIDC/SAML-провайдер, серверная сессия и сопоставление сотрудников с ролями.',hris:'Для HRIS нужны API поставщика, согласованный состав данных и серверная синхронизация.',lms:'Для LMS нужны API каталога и результатов, согласованные идентификаторы навыков и серверный импорт.'};openDialog('Что нужно для подключения',`<p>${details[id]}</p>${banner('В демоверсии соединение не настраивается. Секреты не вводятся в интерфейс.')}`,btn('Понятно','close-dialog','primary'));return;}
    if(action==='reset-demo'){openDialog('Сбросить демоверсию?','<p>Локальные записи, результаты, изменения каталога и настройки будут заменены исходными примерами. Сначала скачайте профиль, если хотите сохранить его.</p>',btn('Отмена','close-dialog')+btn('Сбросить демоверсию','confirm-reset','danger'));return;}
    if(action==='confirm-reset'){db=CQSeed();session={role:'employee'};chat=[];save();closeDialog();go('/app/home');toast('Исходные примеры восстановлены');return;}
    if(action==='sample-toast'||action==='retry-demo'){toast(action==='retry-demo'?'Проверка завершена: демонстрационные данные доступны.':'Действие выполнено');return;}
    if(action==='sample-confirm'){openDialog('Пример подтверждения','<p>Это демонстрация диалога. Данные не будут изменены.</p>',btn('Отмена','close-dialog')+btn('Подтвердить','close-dialog','primary'));return;}
  });
  document.addEventListener('change',event=>{const el=event.target;if(el.dataset.filter){view[el.dataset.filter]=el.value;render();}if(el.dataset.preference){const key=el.dataset.preference;if(key==='profile'){db.profile=el.value;chat=[];}else db.preferences[key]=el.type==='checkbox'?el.checked:el.value;save();render();toast('Настройки сохранены');}});
  document.addEventListener('input',event=>{const el=event.target;if(el.id==='global-search'){searchResults(el.value);return;}if(['catalog-search','people-search','hr-search','users-search','audit-search'].includes(el.id)){view.query=el.value;const position=el.selectionStart,id=el.id;render();const input=document.getElementById(id);input?.focus();input?.setSelectionRange(position,position);}});
  document.addEventListener('submit',async event=>{
    const form=event.target;if(!['chat-form','profile-form','onboarding-form','evidence-form','activity-form','matrix-form','user-form','skill-form','import-form'].includes(form.id)&&!form.classList.contains('review-form'))return;
    event.preventDefault();const data=new FormData(form),get=name=>String(data.get(name)||'').trim();form.querySelector('.form-error')?.remove();
    if(form.id==='chat-form'){askNavigator(get('prompt'));return;}
    if(form.id==='onboarding-form'){db.profile=get('profile');person().target=get('target');db.onboarded=true;session={role:'employee'};save();go('/app/home');toast('Ваш маршрут готов');return;}
    if(form.id==='profile-form'){Object.assign(person(),{name:get('name'),email:get('email'),target:get('target'),goal:get('goal')});save();render();toast('Профиль сохранён');return;}
    if(form.id==='evidence-form'){const e=myEnrollments().find(e=>e.id===form.dataset.id);if(!e||!['enrolled','revision'].includes(e.status)||session.role!=='employee')return;if(get('evidence').length<20)return formError(form,'Опишите результат подробнее: не менее 20 символов.');if(get('link')&&!safeLink(get('link'),'link'))return formError(form,'Используйте ссылку, начинающуюся с https:// или http://.');e.evidence=get('evidence');e.link=get('link');e.status='submitted';e.submittedAt=new Date().toISOString();audit('Отправка результата',activity(e.activityId).title);notify('Результат отправлен на проверку',activity(e.activityId).title,'/app/enrollments/'+e.id);save();render();toast('Результат отправлен руководителю');return;}
    if(form.classList.contains('review-form')){if(session.role!=='manager')return;const e=db.enrollments.find(e=>e.id===form.dataset.id&&e.employeeId==='E0028');if(!e||e.status!=='submitted')return toast('Этот результат уже обработан.');const decision=event.submitter?.value;if(!['verified','revision'].includes(decision))return;if(get('comment').length<10)return formError(form,'Добавьте конкретную обратную связь: не менее 10 символов.');e.status=decision;e.reviewComment=get('comment');e.reviewedAt=new Date().toISOString();const a=activity(e.activityId),p=db.employees.find(p=>p.id===e.employeeId);if(decision==='verified'&&!db.progress.some(x=>x.enrollmentId===e.id)){const s=p.skills.find(s=>s.name===a.skill);if(s){const before=s.level;s.level=Math.min(5,s.level+1);p.readiness=calculateReadiness(p);db.progress.unshift({id:crypto.randomUUID(),enrollmentId:e.id,employeeId:p.id,skill:s.name,before,after:s.level,date:new Date().toISOString()});}}audit(decision==='verified'?'Подтверждение результата':'Возврат на доработку',a.title);notify(decision==='verified'?'Ваш результат подтверждён':'Результат нужно доработать',e.reviewComment,'/app/enrollments/'+e.id,e.employeeId);save();render();toast(decision==='verified'?'Результат подтверждён. Прогресс обновлён.':'Результат возвращён с обратной связью.');return;}
    if(form.id==='activity-form'){if(!['hr','admin'].includes(session.role))return;const existing=activity(form.dataset.id),startsAt=new Date(get('date')+':00+05:00');if(!Number.isFinite(startsAt.getTime()))return formError(form,'Укажите корректные дату и время.');if(!existing&&startsAt<=new Date())return formError(form,'Выберите будущую дату.');const values={title:get('title'),description:get('description'),format:get('format'),skill:get('skill'),date:startsAt.toISOString(),hours:Number(get('hours')),capacity:Number(get('capacity')),owner:get('owner'),location:get('location'),roles:data.getAll('audience').map(String),program:get('program').split(String.fromCharCode(10)).map(s=>s.trim()).filter(Boolean)};if(values.description.length<20||!values.program.length)return formError(form,'Добавьте описание от 20 символов и хотя бы один пункт программы.');if(existing){if(values.capacity<existing.capacity-places(existing))return formError(form,'Вместимость не может быть меньше уже занятых мест.');Object.assign(existing,values);promoteWaitlist(existing.id);audit('Изменение активности',existing.title);}else{const a={...values,id:'ACT_'+crypto.randomUUID(),status:'draft',color:'blue',score:80,booked:0};db.activities.unshift(a);audit('Создание черновика',a.title);form.dataset.id=a.id;}save();go('/hr/activities/'+form.dataset.id);toast('Изменения сохранены');return;}
    if(form.id==='user-form'){if(session.role!=='admin')return;const u=db.users.find(u=>u.id===form.dataset.id);u.role=get('role');u.active=data.get('active')==='on';audit('Изменение демороли',u.name+' · '+roleNames[u.role]);save();closeDialog();render();toast('Демонстрационный справочник обновлён');return;}
    if(form.id==='skill-form'){if(session.role!=='admin')return;const s=db.skills.find(s=>s.id===form.dataset.id),name=get('name');if(db.skills.some(x=>x.id!==s?.id&&x.name.toLowerCase()===name.toLowerCase()))return formError(form,'Навык с таким названием уже есть.');if(s){const old=s.name;s.name=name;s.description=get('description');db.activities.forEach(a=>{if(a.skill===old)a.skill=name;});db.employees.forEach(p=>p.skills.forEach(x=>{if(x.name===old)x.name=name;}));}else db.skills.push({id:'SKILL_'+crypto.randomUUID(),name,description:get('description')});audit(s?'Изменение навыка':'Создание навыка',name);save();closeDialog();render();toast('Навык сохранён');return;}
    if(form.id==='matrix-form'){if(session.role!=='admin')return;const p=db.employees.find(p=>p.id===form.dataset.id);p.skills.forEach((s,i)=>s.target=Number(get('skill-'+i)));p.readiness=calculateReadiness(p);audit('Изменение матрицы',p.role+' · '+p.target);save();render();toast('Матрица сохранена');return;}
    if(form.id==='import-form'){const file=data.get('file');if(!file||file.size>100000)return formError(form,'Выберите JSON-файл размером до 100 КБ.');try{const payload=JSON.parse(await file.text());if(!payload.employee_id||typeof payload.role!=='string'||typeof payload.grade!=='string'||!Number.isFinite(payload.tenure_months)||payload.tenure_months<0||!payload.skills||Array.isArray(payload.skills)||!Object.keys(payload.skills).length)throw Error('Проверьте поля employee_id, role, grade, tenure_months и skills.');const skills=Object.entries(payload.skills).map(([id,level])=>{if(!Number.isInteger(level)||level<1||level>5)throw Error('Уровни навыков должны быть целыми числами от 1 до 5.');const known=db.employees.flatMap(p=>p.skills).find(s=>s.id===id);return {id,name:known?.name||id,level,target:known?.target||Math.min(5,level+1)};});if(skills.length>100)throw Error('В демопрофиле поддерживается до 100 навыков.');const id=String(payload.employee_id);if(!/^[A-Za-z0-9_-]{1,64}$/.test(id))throw Error('employee_id должен содержать только латинские буквы, цифры, дефис или подчёркивание.');if(db.employees.some(p=>p.id===id))throw Error('Профиль с таким employee_id уже существует. Укажите уникальный идентификатор.');db.employees.push({id,name:String(payload.name||'Новый сотрудник'),role:payload.role,grade:payload.grade,target:payload.target||'Senior',tenure:payload.tenure_months,skills,readiness:Math.round(skills.reduce((sum,s)=>sum+Math.min(1,s.level/s.target),0)/skills.length*100),team:'Импортированный профиль',email:'employee@example.com',manager:'Не назначен',goal:'Определить следующий шаг развития',recommended:null});db.profile=id;chat=[];save();closeDialog();go('/app/home');toast('Демопрофиль загружен');}catch(error){formError(form,error instanceof SyntaxError?'Не удалось прочитать JSON. Проверьте формат файла.':error.message);}return;}
  });
  document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'&&session?.role){event.preventDefault();searchDialog();}if(event.key==='Escape'&&menuOpen){menuOpen=false;render();document.querySelector('.mobile-toggle')?.focus();}if(event.key==='Tab'&&menuOpen){const els=[...document.querySelectorAll('.sidebar a,.sidebar button')].filter(x=>x.getClientRects().length),first=els[0],last=els[els.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
  window.addEventListener('hashchange',()=>{if(dialog.open)closeDialog();render();});
  window.addEventListener('storage',event=>{if(event.key===STORE){const fresh=read(STORE,null);if(fresh?.version===3){db=fresh;render();}}});
  if(!roleNames[session?.role])session=null;
  db.employees.forEach(p=>p.readiness=calculateReadiness(p));
  render();
  function settingsPage(section='general'){let body='';if(section==='notifications')body=`<h2>Уведомления</h2>${toggle('inApp','Внутри приложения','Новые ответы и изменения статуса по вашим активностям.')}${toggle('weekly','Еженедельный обзор','Предпочтение для будущего почтового подключения. Письма в демо не отправляются.')}${toggle('reminderDay','За 24 часа до начала','Предпочтение напоминаний для подключённого канала.')}${toggle('reminderHour','За 1 час до начала','Короткое напоминание перед активностью.')}<div class="setting-row"><div><strong>Telegram</strong><p>Одноразовая ссылка выдаётся для записи, созданной через сервер. Подключение доступно в отдельном разделе.</p></div>${tag('Отдельное подключение')}</div><a class="button" href="./telegram.html">${icon('send')}Подключить Telegram</a>`;else if(section==='appearance')body=`<h2>Внешний вид</h2><div class="setting-row"><div><strong>Тема приложения</strong><p>Выберите удобное оформление для работы.</p></div><select aria-label="Тема" data-preference="theme" style="width:auto"><option value="light" ${db.preferences.theme==='light'?'selected':''}>Светлая</option><option value="dark" ${db.preferences.theme==='dark'?'selected':''}>Тёмная</option></select></div>${toggle('reducedMotion','Уменьшить движение','Отключить переходы и анимацию интерфейса.')}`;else if(section==='privacy')body=`<h2>Данные и конфиденциальность</h2><div class="setting-row"><div><strong>Данные демоверсии</strong><p>Изменения сохраняются только в этом браузере. Другие пользователи их не видят.</p></div>${tag('Локально','green','shield')}</div><div class="setting-row"><div><strong>Экспорт профиля</strong><p>Скачайте профиль, навыки и подтверждённые результаты.</p></div>${btn('Скачать','export-profile','','download')}</div><div class="setting-row"><div><strong>Сбросить демоверсию</strong><p>Удалить ваши локальные изменения и вернуть исходные примеры.</p></div>${btn('Сбросить','reset-demo','danger')}</div><div style="margin-top:24px">${textLink('Как обрабатываются данные','/privacy')}</div>`;else body=`<h2>Общие настройки</h2><div class="setting-row"><div><strong>Часовой пояс</strong><p>Даты активностей отображаются в выбранном часовом поясе.</p></div><select aria-label="Часовой пояс" data-preference="timezone" style="width:auto;max-width:220px">${[['Asia/Almaty','Астана · UTC+5'],['Europe/Moscow','Москва · UTC+3'],['UTC','UTC']].map(([k,v])=>`<option value="${k}" ${db.preferences.timezone===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="setting-row"><div><strong>Язык интерфейса</strong><p>Русский</p></div>${tag('RU')}</div><div class="setting-row"><div><strong>Демонстрационный профиль</strong><p>Можно изучить продукт от лица другого сотрудника.</p></div><select aria-label="Демонстрационный профиль" data-preference="profile" style="width:auto;max-width:220px">${db.employees.map(p=>`<option value="${p.id}" ${p.id===person().id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="setting-row"><div><strong>Роль в демоверсии</strong><p>${roleNames[session.role]}. Все данные синтетические.</p></div>${btn('Сменить','switch-role','','users')}</div>`;return heading('Настройки','Ваше пространство, ваш рабочий ритм.')+`<div class="settings-layout"><nav class="settings-nav" aria-label="Разделы настроек">${[['general','Общие'],['notifications','Уведомления'],['appearance','Внешний вид'],['privacy','Данные и приватность']].map(([key,label])=>`<a href="#/app/settings/${key}" class="${section===key?'active':''}">${label}</a>`).join('')}</nav><section class="card card-pad">${body}</section></div>`;}
})();
